    """Complete the rightward continuation on the most extended row of each pattern band."""
    from collections import Counter
    if not grid:
        return []
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    bands=[]
    a=None
    for r in range(len(grid)+1):
        active=r<len(grid) and any(v!=bg for v in grid[r])
        if active and a is None: a=r
        elif not active and a is not None:
            bands.append((a,r-1)); a=None
    # A continuation is indicated by a row whose last foreground run is shorter
    # than the furthest occupied position of another row in the same band.
    for a,b in bands:
        ends={r:max((c for c,v in enumerate(grid[r]) if v!=bg),default=-1) for r in range(a,b+1)}
        far=max(ends.values())
        for r,end in ends.items():
            if end>=0 and end<far and end+1<len(grid[r]) and end>=len(grid[r])//2:
